@Configuration
public class CierreCaptacionFlowConfig {

    /** 50000000-PROCESO-PRINCIPAL como Flow: cada bloque es un Step y cada IF de librería un Decider. */
    @Bean
    Job cierreCaptacionP102(JobRepository repo,
                            Step iniciaS151, Step eliminaS408,
                            Step pagosPendientesYP010,   // 50100000-LEE-BASE UNTIL EOF-B03
                            Step actualizaGlobales,      // 50600000: B09CIFRAS y B14TOTCVES
                            Step beneficencia,           // 51000000: TRSPMANUAL
                            Step esquemasContables,      // 90005094: volcado B22
                            Step actualizaControl,       // 59000000: banderas B02 a cero
                            Step finS151, Step finDiaS408,
                            JobExecutionDecider conS151, JobExecutionDecider conS408,
                            JobExecutionDecider hayArchivoBenef) {
        return new JobBuilder("S500P102", repo)
                .start(conS151).on("SIN_LIB").to(conS408)
                    .from(conS151).on("*").to(iniciaS151).next(conS408)
                .from(conS408).on("SIN_LIB").to(pagosPendientesYP010)
                    .from(conS408).on("*").to(eliminaS408).next(pagosPendientesYP010)
                .next(actualizaGlobales)
                .next(hayArchivoBenef).on("RESIDENTE").to(beneficencia).next(esquemasContables)
                    .from(hayArchivoBenef).on("*").to(esquemasContables)   // reporta NO RESIDENTE
                .next(actualizaControl)
                .next(finS151)                     // REBLOQUEA-01 + S151-FIN
                .next(finDiaS408)                  // función 37: habilita el batch de S408
                .end()
                .build();
    }
}

