// ---------------------------------------------------------------------------
/** 50124000-GEN-ARCH-P010: un abono en cero por contrato con B03-IND-PROTECSDO > 0. */
RegistroDispP010 registroP010(ContratoB03 c, Contexto ctx) {
    int clave = (c.indProtNom() > 0) ? props.claveProtecNomina() : props.claveProtecGeneral();
    return new RegistroDispP010(
            ctx.siguienteAutorizacionP010(),        // WKS-AUT-SEQ
            c.sucPromotora(),
            c.numContrato(),                        // String: conserva ceros
            c.moneda(),
            ctx.fechaProxima(),                     // B02-FECHA-LINEA como referencia
            BigDecimal.ZERO.setScale(2),            // importe siempre 0
            TipoMovimiento.ABONO,                   // TPO-MOV = 2
            clave);
}
// El trailer suma cargos y abonos; como el importe es 0, solo el conteo de abonos crece.
